#[path = "/output/src/earcut.rs"]
mod earcut;

fn spiral(n: i32) -> Vec<[f64; 2]> {
    let mut pts = Vec::new();
    if n > 0 {
        let denom = (2 * n) as f64;
        for i in 0..(2 * n) {
            let t = i as f64 / denom;
            let radius = t;
            let angle = (4.0 * std::f64::consts::PI) * t;
            pts.push([radius * angle.cos(), radius * angle.sin()]);
        }
    }
    pts
}

fn main() {
    // 1. unit square, CCW
    let sq = vec![[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]];
    let tr = earcut::earcut(&sq);
    println!("square: {:?}", tr);
    assert_eq!(tr, vec![2, 3, 0, 0, 1, 2]);

    // 2. same square reversed (CW)
    let mut sq2 = sq.clone();
    sq2.reverse();
    let tr2 = earcut::earcut(&sq2);
    println!("square rev: {:?} ({} tris)", tr2, tr2.len() / 3);
    assert_eq!(tr2.len(), 6);

    // 3. degenerate inputs
    assert!(earcut::earcut(&[]).is_empty());
    assert!(earcut::earcut(&[[1.0, 2.0]]).is_empty());
    assert!(earcut::earcut(&[[0.0, 0.0], [1.0, 1.0]]).is_empty());
    // colinear triple
    let col = earcut::earcut(&[[0.0, 0.0], [1.0, 1.0], [2.0, 2.0]]);
    println!("colinear: {:?}", col);
    // duplicated seam point
    let dup = earcut::earcut(&[[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0], [0.0, 0.0]]);
    println!("dup seam: {:?} ({} tris)", dup, dup.len() / 3);

    // 4. spiral n=7 (default fixture, m=14)
    let s7 = spiral(7);
    let t7 = earcut::earcut(&s7);
    println!("spiral n=7: m={}, tris={}", s7.len(), t7.len() / 3);
    println!("indices: {:?}", t7);
    assert!(t7.len() % 3 == 0);
    for &i in &t7 {
        assert!((i as usize) < s7.len());
    }

    // 5. spiral n=100 (m=200 > 80 -> z-order hashing path)
    let s100 = spiral(100);
    let t100 = earcut::earcut(&s100);
    println!("spiral n=100: m={}, tris={}", s100.len(), t100.len() / 3);
    assert!(t100.len() % 3 == 0);
    for &i in &t100 {
        assert!((i as usize) < s100.len());
    }

    // 6. large simple convex-ish polygon through hashing path (circle, 200 pts)
    let circle: Vec<[f64; 2]> = (0..200)
        .map(|i| {
            let a = i as f64 / 200.0 * 2.0 * std::f64::consts::PI;
            [a.cos(), a.sin()]
        })
        .collect();
    let tc = earcut::earcut(&circle);
    println!("circle m=200: tris={}", tc.len() / 3);
    assert_eq!(tc.len() / 3, 198); // convex polygon: full m-2 triangles

    // 7. determinism: same input twice
    let t7b = earcut::earcut(&spiral(7));
    assert_eq!(t7, t7b);

    println!("ALL_SANITY_OK");
}
